private val Cream=Color(0xFFF7F2E9);private val Coffee=Color(0xFF65422F);private val Tint=Color(0xFFE9E2EA)
private fun money(v:Long)="%,dđ".format(v).replace(',','.');private fun time(v:Long)=SimpleDateFormat("dd/MM HH:mm",Locale.getDefault()).format(Date(v))
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);enableEdgeToEdge();setContent{MaterialTheme(colorScheme=lightColorScheme(primary=Coffee,background=Cream)){Surface(Modifier.fillMaxSize().safeDrawingPadding(),color=Cream){App()}}}}}
@Composable fun App(vm:PosViewModel=viewModel()){val sc by vm.screen.collectAsState();val t by vm.currentTable.collectAsState();val s by vm.currentSession.collectAsState();when(sc){"LOGIN"->Login(vm);"TABLES"->Tables(vm);"ORDER"->t?.let{Order(vm,it)};"SENT"->if(t!=null&&s!=null)Sent(vm,t!!,s!!);"PAY"->if(t!=null&&s!=null)Pay(vm,t!!,s!!);"HISTORY"->History(vm);"REPORT"->Report(vm);"MANAGE"->Manage(vm);"MENU"->Menu(vm);"EMP"->Employees(vm);"PURCHASE"->Purchases(vm);"PRINTER"->Printer(vm);"VIETQR"->VietQr(vm);"SETTINGS"->Settings(vm)}}
@Composable fun Header(title:String="",back:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(18.dp),verticalAlignment=Alignment.CenterVertically){if(back==null)Column{Text("0210",fontSize=32.sp,fontWeight=FontWeight.Black);Text("BREAKFAST · COFFEE · DRINKS",fontSize=9.sp)}else Text("‹",Modifier.clickable{back()}.padding(6.dp),fontSize=36.sp);Spacer(Modifier.weight(1f));Text(title,fontSize=21.sp,fontWeight=FontWeight.Bold)}}
@Composable fun Login(vm:PosViewModel){var pin by remember{mutableStateOf("")};val err by vm.authError.collectAsState();Column(Modifier.fillMaxSize().padding(32.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("0210",fontSize=48.sp,fontWeight=FontWeight.Black);Text("PIN NHÂN VIÊN",fontWeight=FontWeight.Bold);OutlinedTextField(pin,{pin=it.filter(Char::isDigit).take(4)},label={Text("PIN 4 số")},visualTransformation=PasswordVisualTransformation());if(err.isNotBlank())Text(err,color=MaterialTheme.colorScheme.error);Button({vm.login(pin)},Modifier.fillMaxWidth().padding(top=12.dp),enabled=pin.length==4){Text("ĐĂNG NHẬP")};Text("Test: Tuấn 0210 · Hương 1992 · Nam 2000",fontSize=11.sp,modifier=Modifier.padding(top=14.dp))}}
@Composable fun Operator(vm:PosViewModel){val e by vm.currentEmployee.collectAsState();AssistChip({vm.logout()},{Text("🔒 ${e?.name} · ${if(e?.role=="ADMIN")"Quản lý" else "Nhân viên"} · Đổi người")})}
@Composable fun Tables(vm:PosViewModel){val asx by vm.areas.collectAsState();val ts by vm.tables.collectAsState();val ss by vm.sessions.collectAsState();var area by remember{mutableStateOf("inside")};Column{Header();Row(Modifier.padding(horizontal=12.dp)){TextButton({}){Text("BÁN HÀNG",fontWeight=FontWeight.Bold)};TextButton({vm.screen.value="HISTORY"}){Text("LỊCH SỬ")};TextButton({vm.screen.value="REPORT"}){Text("BÁO CÁO")};TextButton({vm.screen.value="MANAGE"}){Text("☰")}};Box(Modifier.padding(horizontal=16.dp)){Operator(vm)};Row(Modifier.padding(horizontal=16.dp)){asx.forEach{FilterChip(area==it.id,{area=it.id},{Text(it.name)},Modifier.padding(2.dp))}};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(ts.filter{it.areaId==area}.chunked(2)){row->Row{row.forEach{tb->val open=ss.firstOrNull{it.tableId==tb.id};Card(Modifier.weight(1f).height(115.dp).padding(5.dp).clickable{vm.selectTable(tb)},colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.fillMaxSize(),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text(tb.name,fontWeight=FontWeight.Bold);Text(if(open==null)"Trống" else "Phục vụ · ${time(open.openedAt)}",fontSize=11.sp)}}};if(row.size==1)Spacer(Modifier.weight(1f))}}};Button({vm.addTable(area)},Modifier.fillMaxWidth().padding(16.dp)){Text("＋ TẠO BÀN")}}}
@Composable fun Order(vm:PosViewModel,t:DiningTableEntity){val cs by vm.categories.collectAsState();val ms by vm.menu.collectAsState();val cart by vm.cart.collectAsState();val e by vm.currentEmployee.collectAsState();var cat by remember(cs){mutableStateOf(cs.firstOrNull()?.id?:"")};Column{Header(t.name){vm.screen.value="TABLES"};Text("🔒 Order: ${e?.name}",Modifier.padding(horizontal=18.dp),color=Coffee);Row(Modifier.padding(8.dp)){cs.take(4).forEach{FilterChip(cat==it.id,{cat=it.id},{Text(it.name)},Modifier.padding(2.dp))}};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(ms.filter{it.categoryId==cat&&it.active}){m->val q=cart[m.id]?:0;Card(Modifier.fillMaxWidth().padding(4.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(m.name,fontWeight=FontWeight.Bold);Text(money(m.price))};if(q>0){Text("−",Modifier.clickable{vm.sub(m)}.padding(12.dp));Text("$q")};Text("＋",Modifier.clickable{vm.add(m)}.padding(12.dp))}}}};Button({vm.sendBatch()},Modifier.fillMaxWidth().padding(16.dp),enabled=cart.isNotEmpty()){Text("GỬI / PREVIEW PHIẾU BẾP")}}}
@Composable fun Sent(vm:PosViewModel,t:DiningTableEntity,s:TableSessionEntity){val bs by vm.batches(s.id).collectAsState(initial=emptyList());val total by vm.total(s.id).collectAsState(initial=0);var pv by remember{mutableStateOf<OrderBatchEntity?>(null)};Column{Header(t.name){vm.screen.value="TABLES"};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(bs){b->Card(Modifier.fillMaxWidth().padding(5.dp).clickable{pv=b},colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(14.dp)){Text("Đơn #${b.sequence.toString().padStart(3,'0')} · ${time(b.createdAt)}",fontWeight=FontWeight.Bold);Text(if(b.status=="SENT")"● Đã xác nhận gửi" else "○ Chưa in · chạm để preview")}}}};Text("Tạm tính ${money(total)}",Modifier.padding(18.dp),fontWeight=FontWeight.Bold);Row(Modifier.padding(16.dp)){OutlinedButton({vm.screen.value="ORDER"},Modifier.weight(1f)){Text("GỌI THÊM")};Button({vm.screen.value="PAY"},Modifier.weight(1f)){Text("THANH TOÁN")}}};pv?.let{b->AlertDialog({pv=null},{Button({vm.markBatchSent(b);pv=null},enabled=b.status!="SENT"){Text("XÁC NHẬN IN / GỬI")}},dismissButton={TextButton({pv=null}){Text("ĐÓNG")}},title={Text("PREVIEW PHIẾU BẾP")},text={Column{Text("0210 · ${t.name}",fontWeight=FontWeight.Black);Text("Đơn #${b.sequence} · ${time(b.createdAt)}");Text("Máy in: ${vm.setting("printer_name").ifBlank{"Chưa chọn"}}")}})}}
@Composable fun Pay(vm:PosViewModel,t:DiningTableEntity,s:TableSessionEntity){val total by vm.total(s.id).collectAsState(initial=0);val e by vm.currentEmployee.collectAsState();var method by remember{mutableStateOf("CASH")};var pv by remember{mutableStateOf(false)};Column{Header("Thanh toán"){vm.screen.value="SENT"};Column(Modifier.weight(1f).padding(18.dp)){Text("TỔNG CỘNG");Text(money(total),fontSize=38.sp,fontWeight=FontWeight.Black);Row{FilterChip(method=="CASH",{method="CASH"},{Text("TIỀN MẶT")});FilterChip(method=="TRANSFER",{method="TRANSFER"},{Text("CHUYỂN KHOẢN")})};Text("🔒 Thu tiền: ${e?.name}",Modifier.padding(vertical=14.dp),fontWeight=FontWeight.Bold);if(method=="TRANSFER")Card(colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(16.dp)){Text("VIETQR",fontWeight=FontWeight.Bold);Text("${vm.setting("bank_name")} · ${vm.setting("bank_account")}");Text("${vm.setting("bank_holder")}");Text("${money(total)} · ${vm.setting("qr_prefix").ifBlank{"0210"}} ${t.name}")}};OutlinedButton({pv=true},Modifier.fillMaxWidth().padding(top=14.dp)){Text("PREVIEW BILL / IN BILL")}};Button({vm.close(method,total)},Modifier.fillMaxWidth().padding(18.dp),enabled=total>0&&(e?.canCheckout==true||e?.role=="ADMIN")){Text("XÁC NHẬN THANH TOÁN")}};if(pv)AlertDialog({pv=false},{Button({pv=false}){Text("IN BILL")}},title={Text("PREVIEW BILL")},text={Column{Text("0210 · ${t.name}");Text("Tổng ${money(total)}");Text("Máy: ${vm.setting("printer_name").ifBlank{"Chưa chọn"}}")}})}
@Composable fun History(vm:PosViewModel){val bs by vm.bills.collectAsState();Column{Header("Lịch sử"){vm.screen.value="TABLES"};LazyColumn(Modifier.padding(14.dp)){items(bs){b->Card(Modifier.fillMaxWidth().padding(4.dp)){Row(Modifier.padding(14.dp)){Text(b.billNo,Modifier.weight(1f));Text(money(b.total),fontWeight=FontWeight.Bold)}}}}}}
@Composable fun Report(vm:PosViewModel){val bs by vm.bills.collectAsState();val ps by vm.purchases.collectAsState();val pays by vm.payments.collectAsState();var r by remember{mutableStateOf("Hôm nay")};val rev=bs.sumOf{it.total};val input=ps.sumOf{it.total};val cash=pays.filter{it.method=="CASH"}.sumOf{it.amount};Column{Header("Báo cáo"){vm.screen.value="TABLES"};LazyColumn(Modifier.padding(16.dp)){item{Row{listOf("Hôm nay","7 ngày","30 ngày").forEach{FilterChip(r==it,{r=it},{Text(it)},Modifier.padding(2.dp))}};Metric("DOANH THU",rev);Text("Tiền mặt ${money(cash)} · CK ${money(rev-cash)}");Metric("NHẬP ĐẦU VÀO",input);Metric("CHÊNH LỆCH THU - NHẬP",rev-input);Card(colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(16.dp)){Text("PHÂN TÍCH 0210",fontWeight=FontWeight.Bold);Text(if(bs.size<5)"Chưa đủ dữ liệu. Cần ít nhất 5 bill để tự động đề xuất." else "Đã đủ dữ liệu cơ sở để phân tích xu hướng.")}}}}}}
@Composable fun Metric(n:String,v:Long){Card(Modifier.fillMaxWidth().padding(5.dp),colors=CardDefaults.cardColors(containerColor=Tint)){Column(Modifier.padding(16.dp)){Text(n);Text(money(v),fontSize=27.sp,fontWeight=FontWeight.Black)}}}
@Composable fun Manage(vm:PosViewModel){Column{Header("Quản lý"){vm.screen.value="TABLES"};LazyColumn(Modifier.padding(16.dp)){item{Operator(vm);Rowx("Menu","Món bán"){vm.screen.value="MENU"};Rowx("Nhân viên","PIN · quyền"){vm.screen.value="EMP"};Rowx("Nhập đầu vào","Ngày giờ · người nhập"){vm.screen.value="PURCHASE"};Rowx("Máy in","Chọn máy · preview"){vm.screen.value="PRINTER"};Rowx("VietQR","Tài khoản nhận tiền"){vm.screen.value="VIETQR"};Rowx("Cài đặt / Nhật ký","Audit thao tác"){vm.screen.value="SETTINGS"}}}}}
@Composable fun Rowx(t:String,s:String,go:()->Unit){Card(Modifier.fillMaxWidth().padding(5.dp).clickable{go()}){Row(Modifier.padding(16.dp)){Column(Modifier.weight(1f)){Text(t,fontWeight=FontWeight.Bold);Text(s,fontSize=12.sp,color=Coffee)};Text("›")}}}
@Composable fun Menu(vm:PosViewModel){val ms by vm.menu.collectAsState();Column{Header("Menu"){vm.screen.value="MANAGE"};LazyColumn(Modifier.padding(12.dp)){items(ms){m->Row(Modifier.fillMaxWidth().padding(12.dp)){Text("${m.name} · ${money(m.price)}",Modifier.weight(1f));Switch(m.active,{vm.toggleMenu(m)})}}}}}
@Composable fun Employees(vm:PosViewModel){val es by vm.employees.collectAsState();Column{Header("Nhân viên"){vm.screen.value="MANAGE"};LazyColumn(Modifier.padding(12.dp)){items(es){e->Card(Modifier.fillMaxWidth().padding(4.dp)){Column(Modifier.padding(14.dp)){Text("${e.name} · ${e.role}",fontWeight=FontWeight.Bold);Text("PIN •••• · Thanh toán ${if(e.canCheckout)"✓" else "—"} · Nhập hàng ${if(e.canPurchase)"✓" else "—"}")}}}}}}
@Composable fun Purchases(vm:PosViewModel){val ps by vm.purchases.collectAsState();val e by vm.currentEmployee.collectAsState();var n by remember{mutableStateOf("")};var a by remember{mutableStateOf("")};var note by remember{mutableStateOf("")};Column{Header("Nhập đầu vào"){vm.screen.value="MANAGE"};Column(Modifier.padding(16.dp)){Text("${time(System.currentTimeMillis())} · 🔒 ${e?.name}");OutlinedTextField(n,{n=it},label={Text("Mặt hàng")});OutlinedTextField(a,{a=it.filter(Char::isDigit)},label={Text("Tổng tiền")});OutlinedTextField(note,{note=it},label={Text("Ghi chú")});Button({vm.addPurchase(n,a.toLongOrNull()?:0,note);n="";a="";note=""},enabled=n.isNotBlank()&&a.toLongOrNull()!=null&&(e?.canPurchase==true||e?.role=="ADMIN")){Text("TẠO PHIẾU")}};LazyColumn(Modifier.padding(16.dp)){items(ps){p->Row(Modifier.fillMaxWidth().padding(8.dp)){Column(Modifier.weight(1f)){Text(p.note);Text(time(p.purchasedAt),fontSize=11.sp)};Text(money(p.total))}}}}}
@Composable fun VietQr(vm:PosViewModel){var b by remember{mutableStateOf(vm.setting("bank_name"))};var a by remember{mutableStateOf(vm.setting("bank_account"))};var h by remember{mutableStateOf(vm.setting("bank_holder"))};var p by remember{mutableStateOf(vm.setting("qr_prefix").ifBlank{"0210"})};Column{Header("VietQR"){vm.screen.value="MANAGE"};Column(Modifier.padding(18.dp)){OutlinedTextField(b,{b=it},label={Text("Ngân hàng")});OutlinedTextField(a,{a=it},label={Text("Số tài khoản")});OutlinedTextField(h,{h=it},label={Text("Chủ tài khoản")});OutlinedTextField(p,{p=it},label={Text("Nội dung CK")});Button({vm.saveSetting("bank_name",b);vm.saveSetting("bank_account",a);vm.saveSetting("bank_holder",h);vm.saveSetting("qr_prefix",p)},Modifier.fillMaxWidth().padding(top=12.dp)){Text("LƯU VIETQR")}}}}
