@Composable fun Settings(vm:PosViewModel){val ls by vm.audits.collectAsState();Column{Header("Nhật ký"){vm.screen.value="MANAGE"};LazyColumn(Modifier.padding(16.dp)){items(ls.take(40)){l->Text("${time(l.occurredAt)} · ${l.actorId?:"SYSTEM"} · ${l.action} · ${l.entityType}",Modifier.padding(5.dp),fontSize=12.sp)}}}}
